        free_cells = b->read_vector_int();
        is_space_vec = b->read_vector_bool();
        eat_timeout = b->read_int();
        egg_timeout = b->read_int();
        eat_time = b->read_int();
        total_enemies = b->read_int();
        total_orbs = b->read_int();
        orbs_collected = b->read_int();
        maze_dim = b->read_int();
    }
